parameters.jsCode:
// 從未聯絡名單中，挑出「搶到時間 + 7 天」剩 <= 2 天（含當天、含已過期）的
// 剩 2/1 天、今天 = 黃燈🟡；已過期 = 紅燈🔴。沒有符合的就回空陣列 → 不推。
// ⚠️ 2026-09-05 事故：Notion 的 select 篩選偶爾回傳索引沒更新的舊值（已改成
//    「已聯絡/無效空號」的 2 筆還是被撈進來），所以這裡一定要再驗一次 payload。
const DAY = 24 * 3600 * 1000;
const results = $input.first().json.results || [];
const now = new Date();

const rows = [];
for (const p of results) {
  const props = p.properties || {};
  const status = (props['聯絡狀態'] && props['聯絡狀態'].select && props['聯絡狀態'].select.name) || '';
  if (status !== '未聯絡') continue; // 防 Notion 篩選回舊值，別拿掉
  const grab = props['搶到時間'] && props['搶到時間'].date && props['搶到時間'].date.start;
  if (!grab) continue; // 沒搶到時間不算
  const deadline = new Date(new Date(grab).getTime() + 7 * DAY);
  const daysLeft = Math.trunc((deadline - now) / DAY); // 與 Notion dateBetween 一致（截斷）
  if (daysLeft > 2) continue; // 以 Notion「🔔 待聯絡」view 為準：推剩≤2天(含今天/過期)
  const name = (props['姓名'] && props['姓名'].title && props['姓名'].title[0] && props['姓名'].title[0].plain_text) || '(未命名)';
  const phone = (props['電話'] && props['電話'].phone_number) || '';
  const city = (props['縣市'] && props['縣市'].select && props['縣市'].select.name) || '';
  const cat = (props['類型'] && props['類型'].select && props['類型'].select.name) || '';
  const acct = (props['帳號'] && props['帳號'].select && props['帳號'].select.name) || '';
  let flag;
  if (daysLeft < 0) flag = '🔴已過期';
  else if (daysLeft === 0) flag = '🟡今天到期';
  else flag = '🟡剩' + daysLeft + '天';
  rows.push({ daysLeft, grab, name, phone, city, cat, acct, flag });
}

if (rows.length === 0) return []; // 沒有待提醒 → 不推

rows.sort((a, b) => a.daysLeft - b.daysLeft); // 最急（已過期）排前面
const phones = Array.from(new Set(rows.map(r => r.phone).filter(Boolean)));
return [{ json: { rows, phones } }];

// 每筆後面標「同電話前一筆」是什麼狀態（只標示、不過濾，重複與否由使用者自己判斷）
const rows = $('挑出快到期未聯絡').first().json.rows || [];
const all = $input.first().json.results || [];

const byPhone = {};
for (const p of all) {
  const props = p.properties || {};
  const ph = (props['電話'] && props['電話'].phone_number) || '';
  const grab = props['搶到時間'] && props['搶到時間'].date && props['搶到時間'].date.start;
  if (!ph || !grab) continue;
  const note = ((props['備註'] && props['備註'].rich_text) || [])
    .map(t => t.plain_text).join('').replace(/\s+/g, ' ').trim();
  byPhone[ph] = byPhone[ph] || [];
  byPhone[ph].push({
    grab,
    status: (props['聯絡狀態'] && props['聯絡狀態'].select && props['聯絡狀態'].select.name) || '(未填)',
    valid: (props['有效性'] && props['有效性'].select && props['有效性'].select.name) || '',
    note: note.replace(/🔁[^｜]*｜前面還有[^：]*/g, '').replace(/^[・\s]+/, '').slice(0, 40)
  });
}

const md = s => String(s).slice(5, 10); // ISO → MM-DD，直接切字串避免時區跑掉

const lines = rows.map(function (r) {
  const parts = [r.name, r.city + r.cat, r.phone, r.acct].filter(Boolean).join('｜');
  let line = '・' + r.flag + '｜' + parts;
  const older = (byPhone[r.phone] || []).filter(x => x.grab < r.grab);
  const prev = older.slice().sort((a, b) => (a.grab < b.grab ? 1 : -1))[0];
  if (prev) {
    let tail = '　↳🔁 同電話前筆(共' + older.length + '筆)｜' + md(prev.grab) + '｜' + prev.status;
    if (prev.valid) tail += '/' + prev.valid;
    if (prev.note) tail += '｜' + prev.note;
    line += '\n' + tail;
  }
  return line;
}).join('\n');

const today = new Date().toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei' });
const text = '🔔 待聯絡提醒 ' + today + '\n以下 ' + rows.length + ' 筆「未聯絡」快到期，記得跟進：\n\n' + lines;
return [{ json: { text } }];
